 *
 ****************************************************************************/

void netdev_lower_carrier_off(FAR struct netdev_lowerhalf_s *dev)
{
#ifdef CONFIG_NET_VLAN
  FAR struct netdev_upperhalf_s *upper = dev->netdev.d_private;
  netdev_upper_vlan_foreach(upper, netdev_lower_carrier_off);
